  def heroicon(name, css_class: 'size-6')
    tag.svg(viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', 'stroke-width': '1.5',
            'aria-hidden': 'true', 'data-slot': 'icon', class: css_class) do
      tag.path(d: OUTLINE_PATHS.fetch(name), 'stroke-linecap': 'round', 'stroke-linejoin': 'round')
    end
  end

  def heroicon_mini(name, css_class: 'size-5')
    tag.svg(viewBox: '0 0 20 20', fill: 'currentColor', 'aria-hidden': 'true', 'data-slot': 'icon',
            class: css_class) do
      tag.path(d: MINI_PATHS.fetch(name), 'fill-rule': 'evenodd', 'clip-rule': 'evenodd')
    end
  end
